-- Capture live state the SQL on disk does not reproduce (item-tools-replay follow-up, replay_check.py).
-- Live is the truth: every statement here is a no-op on the live DB and makes a rebuilt DB (and item-tools)
-- match it.

-- item_weapon_dps_cost: live ran 2026_09_05_00b.sql after 2026_09_05_07/32, but by name it sorts first.
DELETE FROM `item_weapon_dps_cost` WHERE `id` IN (1);
INSERT INTO `item_weapon_dps_cost` (`id`, `cost`) VALUES (1, 1.0);

-- item_weapon_dps_spread: live ran 2026_09_05_00b.sql after 2026_09_05_07/32, but by name it sorts first.
DELETE FROM `item_weapon_dps_spread` WHERE `id` IN (1);
INSERT INTO `item_weapon_dps_spread` (`id`, `spread`) VALUES (1, 0.3);

-- item_template 30086 (Stoneforged Claymore): live stats from a deleted regenerate (guarded on the values the files on
-- disk leave; the float guard is a BETWEEN, which the SQL linter accepts).
UPDATE `item_template` SET `stat_type1` = 3, `stat_value1` = 15, `stat_type2` = 4, `stat_value2` = 17, `dmg_min1` = 181.2888, `dmg_max1` = 336.6792 WHERE `entry` = 30086 AND `stat_type1` = 4 AND `stat_value1` = 26 AND `stat_type2` = 3 AND `stat_value2` = 22 AND `dmg_min1` BETWEEN 144.365 AND 144.385 AND `dmg_max1` BETWEEN 268.115 AND 268.135;

-- item_template 30088 (Skyforged Great Axe): live stats from a deleted regenerate (guarded on the values the files on
-- disk leave; the float guard is a BETWEEN, which the SQL linter accepts).
UPDATE `item_template` SET `stat_value1` = 32, `dmg_min1` = 186.9014, `dmg_max1` = 347.1026 WHERE `entry` = 30088 AND `stat_value1` = 48 AND `dmg_min1` BETWEEN 148.74 AND 148.76 AND `dmg_max1` BETWEEN 276.24 AND 276.26;

